/**
 * otp.js — #/otp (directive §17.3-B #12, §6.3).
 *
 * Six-digit verification. The code is generated by this application's backend and delivered as a
 * local notification (notify.js) because the original SMS gateway is not part of the repository;
 * the screen also shows the code in an in-app banner so the flow never depends on notification
 * permission. `POST /api/auth/otp/verify` completes sign-up and starts the session.
 */

import { api, ApiError } from '../api.js';
import { session, store } from '../store.js';
import { alertDialog, el, render, screen, toast } from '../ui.js';
import { deliverOtp, requestPermission } from '../notify.js';

const RESEND_SECONDS = 45;

export default function otp({ query, navigate }) {
  const phone = query.phone || store.get('pendingOtpPhone', '') || store.get('lastPhone', '');
  const purpose = query.purpose || 'register';

  if (!phone) {
    navigate('#/register', { replace: true });
    return screen([]);
  }

  let busy = false;
  let secondsLeft = RESEND_SECONDS;
  let timer = null;

  const banner = el('div', { class: 'form-note', hidden: true });
  const errorBox = el('p', { class: 'form-error', role: 'alert' });
  const boxes = [];
  const boxRow = el('div', { class: 'otp-boxes' });

  for (let i = 0; i < 6; i += 1) {
    const box = el('input', {
      class: 'otp-box',
      type: 'text',
      inputmode: 'numeric',
      maxlength: '1',
      'aria-label': `Digit ${i + 1}`,
      autocomplete: 'one-time-code',
    });
    box.addEventListener('input', () => {
      box.value = box.value.replace(/\D+/g, '').slice(0, 1);
      if (box.value && i < 5) boxes[i + 1].focus();
      if (boxes.every((b) => b.value)) verify();
    });
    box.addEventListener('keydown', (event) => {
      if (event.key === 'Backspace' && !box.value && i > 0) boxes[i - 1].focus();
      if (event.key === 'ArrowLeft' && i > 0) boxes[i - 1].focus();
      if (event.key === 'ArrowRight' && i < 5) boxes[i + 1].focus();
    });
    box.addEventListener('paste', (event) => {
      const text = (event.clipboardData || window.clipboardData).getData('text') || '';
      const digits = text.replace(/\D+/g, '').slice(0, 6);
      if (!digits) return;
      event.preventDefault();
      digits.split('').forEach((digit, index) => {
        if (boxes[index]) boxes[index].value = digit;
      });
      boxes[Math.min(digits.length, 5)].focus();
      if (digits.length === 6) verify();
    });
    boxes.push(box);
    boxRow.appendChild(box);
  }

  const resendButton = el('button', { type: 'button', class: 'btn btn-ghost', text: 'Resend code' });
  const verifyButton = el('button', { type: 'submit', class: 'btn btn-primary', text: 'Verify' });

  const countdown = el('span', { class: 'muted' });

  function code() {
    return boxes.map((b) => b.value).join('');
  }

  function startCountdown() {
    secondsLeft = RESEND_SECONDS;
    resendButton.disabled = true;
    const tick = () => {
      countdown.textContent = secondsLeft > 0 ? `Resend in ${secondsLeft}s` : '';
      resendButton.disabled = secondsLeft > 0;
      if (secondsLeft <= 0) {
        clearInterval(timer);
        return;
      }
      secondsLeft -= 1;
    };
    tick();
    clearInterval(timer);
    timer = setInterval(tick, 1000);
  }

  function showCode(value) {
    banner.hidden = false;
    render(banner, [
      el('b', { text: 'Your verification code: ' }),
      el('span', { text: value.code }),
      el('span', {
        class: 'tiny muted',
        text: `  (valid ${Math.round((value.expiresInSec || 600) / 60)} min)`,
      }),
    ]);
    deliverOtp(value);
  }

  async function sendCode(initial = false) {
    if (busy) return;
    busy = true;
    errorBox.textContent = '';
    try {
      await requestPermission();
      const value = await api.requestOtp({ phone, purpose });
      showCode(value);
      if (!initial) toast('A new code has been issued');
      startCountdown();
    } catch (err) {
      errorBox.textContent = err instanceof ApiError ? err.message : 'Could not send the code.';
    } finally {
      busy = false;
    }
  }

  async function verify() {
    if (busy) return;
    const entered = code();
    if (entered.length !== 6) {
      errorBox.textContent = 'Enter all six digits.';
      return;
    }
    busy = true;
    verifyButton.disabled = true;
    verifyButton.textContent = 'Verifying…';
    errorBox.textContent = '';
    try {
      const value = await api.verifyOtp({ phone, code: entered, purpose });
      session.set({ authenticated: true, user: value.user });
      store.remove('pendingOtpPhone');
      store.set('lastPhone', phone);
      api.track('otp_verified', { purpose });
      clearInterval(timer);
      toast('Number verified', 'win');
      navigate('#/home', { replace: true });
    } catch (err) {
      errorBox.textContent = err instanceof ApiError ? err.message : 'Verification failed.';
      boxes.forEach((b) => {
        b.value = '';
      });
      boxes[0].focus();
    } finally {
      busy = false;
      verifyButton.disabled = false;
      verifyButton.textContent = 'Verify';
    }
  }

  resendButton.addEventListener('click', () => sendCode(false));

  const form = el('form', { novalidate: true }, [
    errorBox,
    banner,
    boxRow,
    el('div', { class: 'otp-meta' }, [countdown, resendButton]),
    verifyButton,
  ]);

  form.addEventListener('submit', (event) => {
    event.preventDefault();
    verify();
  });

  const changeNumber = el('button', {
    type: 'button',
    class: 'btn btn-ghost',
    text: 'Use a different number',
    onclick: () => navigate('#/register'),
  });

  // The code was issued by the register screen (or a previous visit): show it immediately so the
  // user never has to wait for a notification, then let them resend if it expired.
  (async () => {
    const known = store.get('pendingOtpPhone', '');
    const knownCode = store.get('pendingOtpCode', '');
    if (known === phone && knownCode) {
      banner.hidden = false;
      render(banner, [
        el('b', { text: 'Your verification code: ' }),
        el('span', { text: knownCode }),
      ]);
      store.remove('pendingOtpCode');
      startCountdown();
    } else {
      await sendCode(true);
    }
    boxes[0].focus();
  })();

  return screen([
    el('div', { class: 'auth' }, [
      el('div', { class: 'auth-logo' }, [
        el('img', { src: '../assets/img/splash_logo.jpg', alt: 'Sige77' }),
        el('h1', { text: 'Verify your number' }),
      ]),
      el('p', { class: 'otp-phone' }, [
        'Enter the 6-digit code for ',
        el('b', { text: phone }),
      ]),
      el('p', {
        class: 'tiny muted',
        text:
          'This build has no SMS gateway: the code is generated on this server and shown here and ' +
          'in your notifications, so the number itself is not confirmed.',
      }),
      form,
      changeNumber,
    ]),
  ]);
}
